import unittest

from alpha.greeting import greeting


class GreetingTest(unittest.TestCase):
    def test_default_greeting(self):
        self.assertEqual(greeting(), "hello, demo")

    def test_none_is_default(self):
        self.assertEqual(greeting(None), "hello, demo")

    def test_name_at_limit_is_accepted(self):
        result = greeting("a" * 64)
        self.assertIsInstance(result, str)

    def test_name_over_limit_raises(self):
        with self.assertRaises(ValueError) as ctx:
            greeting("a" * 65)
        self.assertIn("64", str(ctx.exception))

    def test_limit_counts_code_points_not_bytes(self):
        # 64 code points, each 4 bytes in UTF-8: within the limit.
        greeting("\U0001F600" * 64)
        with self.assertRaises(ValueError):
            greeting("\U0001F600" * 65)

    def test_limit_counts_code_points_not_graphemes(self):
        # "e" + combining acute accent: 2 code points per visible character.
        # 33 of them make 66 code points, over the limit.
        with self.assertRaises(ValueError):
            greeting("é" * 33)


if __name__ == "__main__":
    unittest.main()

